      @Measure.map (Fin n → Ω) (ℝ × ℝ × ℝ) mN (borel (ℝ × ℝ × ℝ))
        (fun ξ : Fin n → Ω => (Ddel ξ i, Jdel ξ i, B1del ξ i)) P ∧
